//! Initial paired objects generated by the race marker graph. This prepares
//! construction requests, not a running race, buoy behavior or mission readiness.
use giants_formats::mission::{Mission, ObjectRef};
use std::collections::BTreeMap;

#[derive(Clone, Debug)]
pub struct Point {
    pub source_offset: usize,
    pub ordinal: u32,
    pub position: [f32; 3],
    pub yaw: f32,
    pub omit_pair: bool,
    pub width: f32,
}

#[derive(Clone, Debug)]
pub struct Spawn {
    pub source_offset: usize,
    pub side: usize,
    pub position: [f32; 3],
    pub yaw: f32,
    /// Sequential child ordinal within one native marker group.
    pub ordinal: u32,
}

/// Closed marker ordering, including sparse authored ordinals. The tangent is
/// normalized before applying width, retaining the native binary32 stores.
/// Z is supplied later by the terrain query and clamped to sea level.
pub fn pairs(points: &[Point]) -> Result<Vec<Spawn>, String> {
    if !(3..98).contains(&points.len()) {
        return Err("race marker graph requires 3..97 points".into());
    }
    let mut ordered = BTreeMap::new();
    for point in points {
        if point.ordinal >= 100
            || !point
                .position
                .into_iter()
                .chain([point.yaw, point.width])
                .all(f32::is_finite)
            || point.width < 0.
            || ordered.insert(point.ordinal, point).is_some()
        {
            return Err("invalid or ambiguous race marker point".into());
        }
    }
    if !ordered.contains_key(&0) {
        return Err("race marker root ordinal is absent".into());
    }
    let ordered: Vec<_> = ordered.into_values().collect();
    let mut result = Vec::new();
    for (index, point) in ordered.iter().enumerate() {
        let previous = ordered[(index + ordered.len() - 1) % ordered.len()];
        let next = ordered[(index + 1) % ordered.len()];
        let delta: [f32; 3] = std::array::from_fn(|i| previous.position[i] - next.position[i]);
        let [x, y, z] = delta.map(f64::from);
        let squared = (x * x + y * y) + z * z;
        if squared <= 0. || !squared.is_finite() {
            return Err("degenerate race marker tangent".into());
        }
        let inverse = 1. / squared.sqrt();
        let tangent = delta.map(|v| (f64::from(v) * inverse) as f32);
        if point.omit_pair {
            continue;
        }
        for side in 0..2 {
            let dx = f64::from(-tangent[1]) * f64::from(point.width);
            let dy = f64::from(tangent[0]) * f64::from(point.width);
            let sign = if side == 0 { 1. } else { -1. };
            result.push(Spawn {
                ordinal: result.len() as u32,
                source_offset: point.source_offset,
                side,
                position: [
                    (f64::from(point.position[0]) + sign * dx) as f32,
                    (f64::from(point.position[1]) + sign * dy) as f32,
                    0.,
                ],
                yaw: point.yaw,
            });
        }
    }
    Ok(result)
}

/// The native paired-buoy consumer selects class1098 marker groups. Other
/// marker classes and missing/default object-word policies remain separate.
pub fn from_mission(mission: &Mission) -> Result<Vec<Spawn>, String> {
    let mut groups = BTreeMap::<u8, Vec<Point>>::new();
    for (index, placement) in mission.placements.iter().enumerate() {
        if placement.object_type != 1098 {
            continue;
        }
        let owner = ObjectRef::Placement(index);
        let selector = mission
            .object_selectors
            .iter()
            .rev()
            .find(|r| r.object == owner)
            .ok_or("race marker selector/default is unresolved")?
            .value;
        if selector == 0 {
            continue;
        }
        let words = mission
            .object_words
            .iter()
            .rev()
            .find(|r| r.object == owner)
            .ok_or("race marker object words/defaults are unresolved")?
            .words;
        let gate = f32::from_bits(words[1]);
        if !gate.is_finite() {
            return Err("non-finite race marker pair gate".into());
        }
        let ordinal = mission
            .object_properties
            .iter()
            .rev()
            .find(|r| r.object == owner)
            .map_or(0, |r| r.value);
        groups.entry(selector).or_default().push(Point {
            source_offset: placement.source_offset,
            ordinal,
            position: placement.position,
            yaw: placement.yaw,
            omit_pair: gate != 0.,
            width: f32::from_bits(words[2]),
        });
    }
    let mut result = Vec::new();
    for points in groups.values() {
        result.extend(pairs(points)?);
    }
    Ok(result)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn sparse_closed_graph_and_omitted_pairs_preserve_neighbor_tangents() {
        let mut points: Vec<_> = [
            (0, [0., 0., 0.]),
            (3, [10., 0., 0.]),
            (8, [10., 10., 0.]),
            (20, [0., 10., 0.]),
        ]
        .into_iter()
        .map(|(ordinal, position)| Point {
            ordinal,
            position,
            source_offset: ordinal as usize,
            yaw: 0.,
            omit_pair: false,
            width: 2.,
        })
        .collect();
        let all = pairs(&points).unwrap();
        assert_eq!(all.len(), 8);
        assert!(all[0].position[0] < 0. && all[0].position[1] < 0.);
        assert!(all[1].position[0] > 0. && all[1].position[1] > 0.);
        points[1].omit_pair = true;
        let omitted = pairs(&points).unwrap();
        assert_eq!(omitted.len(), 6);
        assert_eq!(omitted[0].position, all[0].position);
        points[1].ordinal = 0;
        assert!(pairs(&points).is_err());
    }
}
